"""Move learn offer eligibility, probability, and weighted sampling."""from typing import Literalimport randomimport uuidfrom app.core.math import weighted_samplefrom app.domains.move.entity import Movefrom app.domains.move.types import VibemonTypeTfrom app.providers.helpers import move_assignment_weightOFFER_PROBABILITY_BELOW_FOUR = 0.50OFFER_PROBABILITY_PER_LEVEL = 0.15LEVEL_WEIGHT_EXPONENT = 1.5OfferPhase = Literal["kit_building", "upgrade"]def learned_and_forgotten_ids(history_events: tuple[dict[str, object], ...]) -> set[str]:    """Project moves excluded from offer sampling.    Birth ``move_learned`` events (no ``outcome`` field) count as learned.    ``outcome=kept`` counts as learned. ``outcome=rejected`` does not — declined    moves may reappear (decline writes no history today; branch supports future    or manual events). ``move_forgotten`` always excludes.    """    excluded: set[str] = set()    for event in history_events:        event_type = event.get("event_type")        payload = event.get("payload")        if not isinstance(payload, dict):            continue        if event_type == "move_learned":            outcome = payload.get("outcome")            if outcome is not None and outcome != "kept":                continue            move_id = payload.get("move_content_id")            if isinstance(move_id, str):                excluded.add(move_id)        elif event_type == "move_forgotten":            move_id = payload.get("move_content_id")            if isinstance(move_id, str):                excluded.add(move_id)    return excludeddef provider_eligible_moves(    provider_moves: tuple[Move, ...],    level: int,    *,    exclude_ids: set[str],) -> tuple[Move, ...]:    """Birth-provider moves eligible at ``level``, minus excluded ids."""    return tuple(move for move in provider_moves if move.level_requirement <= level and move.id not in exclude_ids)def eligible_with_universal_fallback(    provider_moves: tuple[Move, ...],    universal_moves: tuple[Move, ...],    *,    exclude_ids: set[str],    level: int,    min_count: int = 4,) -> tuple[Move, ...]:    """Return provider pool; append universal moves only when the pool is thin."""    eligible = provider_eligible_moves(provider_moves, level, exclude_ids=exclude_ids)    if len(eligible) >= min_count:        return eligible    seen = {move.id for move in eligible}    pool = list(eligible)    for move in universal_moves:        if move.level_requirement > level or move.id in exclude_ids or move.id in seen:            continue        pool.append(move)        seen.add(move.id)    return tuple(pool)def should_offer(*, active_move_count: int, levels_crossed: int, rng: random.Random) -> bool:    """Roll once per level jump — flat 50% below four moves, additive cap at four."""    if levels_crossed <= 0:        return False    if active_move_count < 4:        return rng.random() < OFFER_PROBABILITY_BELOW_FOUR    probability = min(1.0, levels_crossed * OFFER_PROBABILITY_PER_LEVEL)    return rng.random() < probabilitydef _rankings_for_sampling(    element_rankings: dict[VibemonTypeT, float] | None,    *,    elements: tuple[VibemonTypeT, ...],) -> dict[VibemonTypeT, float]:    if element_rankings:        return element_rankings    return {element: 1.0 - index * 0.01 for index, element in enumerate(elements)}def _move_weights(    moves: tuple[Move, ...],    *,    elements: tuple[VibemonTypeT, ...],    element_rankings: dict[VibemonTypeT, float] | None = None,) -> list[float]:    rankings = _rankings_for_sampling(element_rankings, elements=elements)    return [        move_assignment_weight(            move,            rankings=rankings,            elements=elements,            level_weight_exponent=LEVEL_WEIGHT_EXPONENT,        )        for move in moves    ]def sample_move_options(    moves: tuple[Move, ...],    *,    elements: tuple[VibemonTypeT, ...],    element_rankings: dict[VibemonTypeT, float] | None = None,    k: int = 4,    rng: random.Random,) -> tuple[Move, ...]:    """Weighted sample without replacement; may return fewer than ``k`` when pool is tiny."""    if not moves:        return ()    weights = _move_weights(moves, elements=elements, element_rankings=element_rankings)    return tuple(        weighted_sample(list(moves), weights, k=min(k, len(moves)), rng=rng),    )def offer_rng(*, battle_id: uuid.UUID, vibemon_id: uuid.UUID, salt: str = "move_offer") -> random.Random:    """Deterministic battle-scoped RNG for offer rolls and samples."""    seed = int.from_bytes(uuid.uuid5(battle_id, f"{vibemon_id}:{salt}").bytes[:8], "big")    return random.Random(seed)def auto_pick_from_sample(    sample: tuple[Move, ...],    *,    elements: tuple[VibemonTypeT, ...],    element_rankings: dict[VibemonTypeT, float] | None = None,    rng: random.Random,) -> Move | None:    """Weighted pick from a fixed offer sample (wild auto-resolve)."""    if not sample:        return None    weights = _move_weights(sample, elements=elements, element_rankings=element_rankings)    return weighted_sample(list(sample), weights, k=1, rng=rng)[0]def replacement_slot_index(moves: tuple[Move, ...]) -> int:    """Replace the active move with the lowest ``level_requirement``; tie-break by slot."""    return min(range(len(moves)), key=lambda index: (moves[index].level_requirement, index))